from pathlib import Path
import json,html,shutil,urllib.parse
R=Path(__file__).resolve().parents[2];e=html.escape
D=json.loads((R/'src/data/pyramidMembership.json').read_text());C=json.loads((R/'src/data/pyramidCoverage.json').read_text());T=json.loads((R/'src/data/topMembershipCorrections.json').read_text())
for f in ['pyramidMembership.json','pyramidCoverage.json','reserveClubs.json','topMembershipCorrections.json']:shutil.copyfile(R/'src/data'/f,R/'public/data'/f)
rows=[]
for d in D+T:
 u=d['sourceUrl'];hist=u.replace('/wiki/','/w/index.php?title=')+'&action=history' if 'wikipedia.org/wiki/' in u else None
 pinned=(u.replace('/wiki/','/w/index.php?title=')+'&oldid='+str(d['revision'])) if hist and d.get('revision') else u
 rows.append(f'<tr><td>{e(d["name"])}</td><td>{len(d["clubs"])}</td><td>{e(d.get("sourceSeason",d.get("wiki","")))}</td><td><a href="{e(pinned)}">المصدر</a>'+ (f' · <a href="{e(hist)}">المساهمون</a>' if hist else '')+'</td></tr>')
coverage=''.join(f'<tr><td>{e(c["nameAr"])}</td><td>{c["lowerCompetitions"]}</td><td>{c["lowerClubs"]}</td><td>{e(c["note"])}</td></tr>' for c in C)
old=R/'public/lower-data-license.html';shutil.copyfile(old,R/'public/legacy-lower-data-license.html') if not (R/'public/legacy-lower-data-license.html').exists() else None
text='''<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>مصادر أندية الدرجات — 0.8</title><style>body{font:17px/1.9 system-ui;background:#14251f;color:#e8efe9;padding:24px;max-width:1100px;margin:auto}a{color:#c1ed96}td,th{padding:12px;border-bottom:1px solid #415748;text-align:start}table{width:100%;font-size:14px;overflow-wrap:anywhere}.scroll{overflow:auto}li{overflow-wrap:anywhere}.notice{border-inline-start:4px solid #c1ed96;padding:12px;background:#20372b}</style><a href="/">العودة للعبة</a><h1>مصادر أندية الدرجات وحدود 0.8</h1><p>مراجعة 26 سبتمبر 2026. 50 سوقًا أعلى، و66 مسابقة أقل تضم 1072 ناديًا في 47 سوقًا. ثلاث حالات لم تكتمل: المغرب وبوليفيا وقطر. لا أندية مخترعة لملء النواقص ولا ادعاء بإكمال الهرم كله.</p><p>الخمسة الكبار حتى المستوى الثالث: إنجلترا، ألمانيا، فرنسا (Ligue 3، 18 ناديًا)، إسبانيا (مجموعتان من 20)، إيطاليا (ثلاث مجموعات من 20). مصر حتى المستوى الثالث الفعلي: الممتاز ثم الثانية أ 20 ثم الثانية ب 70 في خمس مجموعات؛ ليس الدوري المسمى الثالثة/المستوى الرابع. اسكتلندا إلى الثاني في البدايات الجديدة. المستويات والفرق الزائدة في الحفظات القديمة تظل محفوظة.</p><div class="notice">الأسماء والعضوية مقتبسة من مصادر منشورة، وليست اعتماد تسجيل اتحادي لكل لاعب أو نادٍ. قوائم اللاعبين الأعلى لم يعاد توثيقها بالكامل. اللاعبون المولّدون يُعرضون كأي لاعب، مع احتفاظ السجل الداخلي بالمصدر. تُستكمل القوائم الناقصة إلى 22 لاعبًا في المشاوير الجديدة فقط؛ القدرات والعقود والأموال تقديرات محاكاة.</div><h2>القواعد المطبقة فعلًا</h2><ul><li>الجداول ذهاب وإياب في المحاكاة؛ ليست كل المراحل المحلية والروزنامة الحقيقية.</li><li>ملاحق الثانية ب المصرية كما في التحديث السابق: أربعة فرق للصعيد ذهاب وإياب إلى مقعد؛ وستة للقاهرة والقناة وبحري من دور واحد إلى مقعدين.</li><li>خارج مصر، الصعود ترتيبي مبسط: مؤهل من كل مجموعة ثم أفضل التاليين بالنقاط لكل مباراة وفارق الأهداف لكل مباراة. ليست الملاحق الإقصائية الرسمية لإسبانيا وإيطاليا وفرنسا وغيرها. لا قرعة جغرافية موسمية لإعادة تقسيم المجموعات.</li><li>مقاعد الخمسة الكبار من الثاني للأول: 3 لإنجلترا وإسبانيا وإيطاليا، و2 لألمانيا وفرنسا. من الثالث للثاني: 3 لإنجلترا، 4 لإسبانيا وإيطاليا، و2 لألمانيا وفرنسا. البراج بين المستويين غير منفذ. باقي المسارات المفتوحة مقعدان في السيناريو؛ مصر ثلاثة.</li><li>39 فريق رديف/تابع له سقف وصلة بفريقه الأول. لا صعود إلى مستوى الفريق الأول أو فوقه. الرديف الألماني لا يصعد للثاني. لا قواعد أعمار أو انتقال داخلي بين الفريقين بعد.</li><li>عند نزول الفريق الأول يمكن إنزال الرديف إذا توفر مستوى أدنى. عند نهاية الهرم المحاكى يُلغى التبادل المخالف بالكامل؛ هذا قيد للنموذج يحمي العضوية، وليس لائحة الاتحاد الحقيقية.</li><li>USL Championship وأستراليا والمكسيك دون صعود تلقائي إلى المستوى الأعلى في هذا السيناريو. أستراليا ممثلة بجدول مبسط لا صيغة البطولة الوطنية كاملة. قيود التراخيص والقبول الخاصة بكل اتحاد ليست مكتملة.</li><li>لا يُحذف لاعب أو نادي قديم عند الترحيل؛ كتالوج البداية منفصل عن سجل التوافق. أُصلحت تعارضات البرتغال وهولندا والنمسا وروسيا مع مراجعة قوائم المستوى الأعلى المرتبطة.</li></ul><h2>التغطية بلدًا ببلد</h2><div class="scroll"><table><tr><th>السوق</th><th>مسابقات أقل</th><th>أندية أقل</th><th>الوضع والحدود</th></tr>'''+coverage+'''</table></div><h2>الإسناد والتراخيص</h2><p>جداول أسماء ويكيبيديا من مساهمي المقالات بترخيص <a href="https://creativecommons.org/licenses/by-sa/4.0/">CC BY-SA 4.0</a>، والجزء المكيف بنفس الترخيص. التغييرات: اختيار موسم وجداول ومجموعات، تسوية اختلاف أسماء، فصل الرديف عن الفريق الأول، وتعيين معرفات ومستويات. روابط المراجعات المثبتة حيث وفرها المصدر؛ لا نسمي الرابط غير المثبت لقطة محفوظة. التجميعات الخبرية للسعودية والإمارات وتونس وفنزويلا حقائق أسماء ومجموعات فقط؛ حقوق المقالات والصور باقية لأصحابها، وليست قواعد لاعبين مفتوحة المصدر.</p><p><a href="/data/pyramidMembership.json">قوائم المستويات الجديدة JSON</a> · <a href="/data/pyramidCoverage.json">التغطية والنواقص JSON</a> · <a href="/data/topMembershipCorrections.json">تصحيحات الأعلى JSON</a> · <a href="/data/reserveClubs.json">روابط الرديف JSON</a> · <a href="/data/egypt-pyramid.json">مراجع مصر والتعارضات JSON</a> · <a href="/legacy-lower-data-license.html">إسناد كتالوج 0.7 التاريخي ومصر</a> · <a href="/data-license.html">مصادر اللاعبين</a></p><div class="scroll"><table><tr><th>المسابقة</th><th>عدد الأندية</th><th>مرجع الموسم</th><th>الإسناد</th></tr>'''+''.join(rows)+'''</table></div><p>لا انتماء رسمي للأندية أو الاتحادات ولا ضمان لأداء آيفون فعلي؛ اختبارات الواجهة الآلية ليست اختبار جهاز حقيقي. المصادر المعروضة ليست تعليمات للعبة ولا تُحمّل عبر الشبكة أثناء اللعب.</p></html>'''
old.write_text(text)
p=R/'public/competition-notes.html';s=p.read_text();s=s.replace('</body>','<section><h2>تحديث الدرجات 0.8</h2><p>الخمسة الكبار ومصر إلى المستوى الثالث؛ بقية الأسواق إلى الثاني حيث اكتملت المراجعة. الملاحق غير المصرية ما زالت مبسطة. راجع <a href="/lower-data-license.html">التغطية والقواعد الحالية والاستثناءات</a>؛ تتقدم هذه الملاحظة على أي وصف تاريخي لأعداد المسابقات.</p></section></body>');p.write_text(s)
print('Published v08 attribution and coverage')
